import { Injectable, signal } from '@angular/core';
import { AngularFireAuth } from '@angular/fire/compat/auth';
import { AngularFirestore } from '@angular/fire/compat/firestore';
import { combineLatest, from, map, mergeMap, mergeMapTo, Observable } from 'rxjs';
import { User } from '../user/user.model';

@Injectable({
  providedIn: 'root',
})
export class UsersService {
  isLoggedIn$: Observable<boolean>;
  isLoggedOut$: Observable<boolean>;
  userAuthData$: Observable<any>;
  combinedUser$: Observable<any>;

  constructor(private fire: AngularFirestore, private fireAuth: AngularFireAuth) {
    fireAuth.idToken.subscribe((jwt) => console.log('jwt', jwt));
    fireAuth.authState.subscribe((auth) => console.log('auth', auth));

    this.isLoggedIn$ = fireAuth.authState.pipe(
      map((user) => {
        console.log('WE FIRED THE CONSTRUCTOR OBSERVE', user);
        return !!user?.multiFactor;
      })
    );
    this.isLoggedOut$ = this.isLoggedIn$.pipe(map((loggedIn) => !loggedIn));

    this.userAuthData$ = fireAuth.authState.pipe(map((user) => user));

    /* Get FireAuth user and combine with our own SiteUser data */
    this.combinedUser$ = fireAuth.authState.pipe(
      mergeMap((user) => this.fetchSiteUser(user?.email || ''))
    );
  }

  createUserWithEmailAndPassword(email: string, password: string) {
    return this.fireAuth
      .createUserWithEmailAndPassword(email, password)
      .then((newuser) => {
        console.log('Created the user!!', newuser);
      })
      .catch((e) => {
        console.error('User creation error', e);
      });
  }

  signInWithEmailAndPassword(email: string, password: string) {
    return this.fireAuth
      .signInWithEmailAndPassword(email, password)
      .then((x) => {
        console.log('Signed in!!', x);
      })
      .catch((e) => {
        console.error('Sign in Error', e);
        throw e;
      });
  }

  signOut() {
    return this.fireAuth
      .signOut()
      .then((x) => {
        console.log('Signed Out!!', x);
      })
      .catch((e) => {
        console.error('Sign Out Error', e);
      });
  }

  sendResetPassword(email: string) {
    const settings = { url: 'http://balancedmediadiet.com' };
    return this.fireAuth.sendPasswordResetEmail(email, settings);
  }

  addUser(newUser: User, userId?: string): Observable<User> {
    return from(this.fire.collection('siteUsers').add(newUser)).pipe(
      map((addedUser) => {
        return {
          id: addedUser.id,
          ...newUser,
        };
      })
    );
  }

  fetchSiteUser(email: string) {
    return from(
      this.fire.collection('siteUsers', (ref) => ref.where('email', '==', email).limit(1)).get()
    ).pipe(
      map((userList) => {
        if (userList.empty) return null;
        const user = userList.docs[0];
        return { ...(user.data() as Object), id: user.id };
      })
    );
  }

  updateUser(userId: string, changes: Partial<User>): Observable<any> {
    return from(this.fire.doc(`siteUsers/${userId}`).update(changes));
  }
}
