import { Component, OnInit } from '@angular/core';
import { map } from 'rxjs/operators';
import { UtilityService } from '../services/utility.service';
import { DietsService } from '../services/diets.service';
import { NzModalRef, NzModalService } from 'ng-zorro-antd/modal';
import { ProfileComponent } from '../user/profile/profile.component';
import { UsersService } from '../services/users.service';

@Component({
  selector: 'bmd-nav',
  templateUrl: './nav.component.html',
  styleUrls: ['./nav.component.scss'],
})
export class NavComponent implements OnInit {
  currentYear = 2024;
  userFeatureFlag = true;
  primaryDiets: any[] = [];

  isLoggedIn$ = this.usersSvc.isLoggedIn$;
  userDisplayName$ = this.usersSvc.userAuthData$.pipe(
    map((user) => user?.displayName || user?.email?.split('@')[0] || null)
  );

  profileModal!: NzModalRef;

  constructor(
    private dietsSvc: DietsService,
    private usersSvc: UsersService,
    private modal: NzModalService,
    private util: UtilityService
  ) {}

  ngOnInit(): void {
    this.dietsSvc.fetchDietsByYear(this.currentYear).subscribe((diets) => {
      diets.forEach((diet) => {
        this.primaryDiets.push(diet);
      });
    });
  }

  // navigate(sectionId: string) {
  //   if (this.route.snapshot.toString() === 'home') {
  //     this.scroll(sectionId);
  //   } else {
  //     this.router.navigate
  //   }
  // }

  gotoDiet(dietSectionId: string) {
    this.dietsSvc.homeDietsOpen.push(dietSectionId);
    console.log('Now our DietsSvcDietsOpen', this.dietsSvc.homeDietsOpen);
    this.scroll(dietSectionId);
  }

  scroll = (sectionId: string) => this.util.scroll(sectionId);

  openProfileModal() {
    this.profileModal = this.modal.create({
      nzFooter: null,
      nzWidth: 400,
      nzCentered: true,
      nzClassName: 'news-source-modal',
      nzContent: ProfileComponent,
      nzData: { modalCloser: this.closeProfileModal.bind(this) },
    });
  }

  closeProfileModal() {
    this.profileModal.close();
  }
}
