import { Component, OnInit, OnDestroy } from '@angular/core';
import { AngularFirestore } from '@angular/fire/compat/firestore';
import { NzMessageService } from 'ng-zorro-antd/message';
import { Subject, Subscription } from 'rxjs';
import { debounceTime } from 'rxjs/operators';

@Component({
  selector: 'news-source-create',
  templateUrl: './news-source-create.component.html',
  styleUrls: ['./news-source-create.component.scss'],
})
export class NewsSourceCreateComponent implements OnInit, OnDestroy {
  name = '';
  description = '';
  type = '';
  category = '';
  foodGroup = '';
  viewpoint = '';
  year: number | null = null;
  journalistName = '';
  hasPaywall = false;
  linkToRead = '';
  linkToWatch = '';
  linkToListen = '';
  imageName = '';

  isSaving = false;
  similarSources: string[] = [];

  private allSourceNames: string[] = [];
  private nameSubject = new Subject<string>();
  private nameSub: Subscription;

  typeOptions = [
    { label: 'Network', value: 'Network' },
    { label: 'Magazine/Newspaper', value: 'Magazine' },
    { label: 'Individual Journalist', value: 'Journalist' },
  ];

  categoryOptions = [
    { label: 'Corporate', value: 'Corporate' },
    { label: 'Independent', value: 'Independent' },
  ];

  private allFoodGroupOptions = [
    { label: 'Corporate Party Politics', value: 'Corporate Party Politics' },
    { label: 'Independent Party Politics', value: 'Independent Party Politics' },
    { label: 'Independent True Politics', value: 'Independent True Politics' },
    { label: 'Independent Deep Politics', value: 'Independent Deep Politics' },
    { label: 'Foreign Politics', value: 'Foreign Politics' },
  ];

  private corporateFoodGroupOptions = [
    { label: 'Corporate Party Politics', value: 'Corporate Party Politics' },
    { label: 'Foreign Politics', value: 'Foreign Politics' },
  ];

  private independentFoodGroupOptions = [
    { label: 'Independent Party Politics', value: 'Independent Party Politics' },
    { label: 'Independent True Politics', value: 'Independent True Politics' },
    { label: 'Independent Deep Politics', value: 'Independent Deep Politics' },
    { label: 'Foreign Politics', value: 'Foreign Politics' },
  ];

  filteredFoodGroupOptions = [...this.allFoodGroupOptions];

  private allViewpointOptions = [
    { label: 'Democrat', value: 'Democrat' },
    { label: 'Republican', value: 'Republican' },
    { label: 'Progressive/Liberal', value: 'Progressive' },
    { label: 'Conservative/Libertarian', value: 'Conservative' },
    { label: 'Nonpartisan', value: 'Nonpartisan' },
    { label: 'International', value: 'International' },
  ];

  private partyViewpointOptions = [
    { label: 'Democrat', value: 'Democrat' },
    { label: 'Republican', value: 'Republican' },
  ];

  private trueViewpointOptions = [
    { label: 'Progressive/Liberal', value: 'Progressive' },
    { label: 'Conservative/Libertarian', value: 'Conservative' },
  ];

  filteredViewpointOptions = [...this.allViewpointOptions];

  constructor(private firestore: AngularFirestore, private message: NzMessageService) {}

  ngOnInit(): void {
    this.nameSub = this.nameSubject
      .pipe(debounceTime(400))
      .subscribe((name) => this.checkForDuplicates(name));

    this.firestore
      .collection('newsSources')
      .get()
      .subscribe((snapshot) => {
        this.allSourceNames = snapshot.docs.map((d) => (d.data() as any).name as string);
      });
  }

  ngOnDestroy(): void {
    this.nameSub?.unsubscribe();
  }

  onNameChange(val: string): void {
    this.nameSubject.next(val);
  }

  private checkForDuplicates(name: string): void {
    if (!name.trim()) {
      this.similarSources = [];
      return;
    }
    const lower = name.trim().toLowerCase();
    this.similarSources = this.allSourceNames.filter((n) => {
      const nl = n.toLowerCase();
      return nl.includes(lower) || lower.includes(nl);
    });
  }

  onTypeChange(type: string): void {
    if (type !== 'Journalist') {
      this.journalistName = '';
    }
    if (type === 'Network') {
      this.category = 'Corporate';
      this.onCategoryChange('Corporate');
    }
  }

  onCategoryChange(category: string): void {
    if (category === 'Corporate') {
      this.filteredFoodGroupOptions = this.corporateFoodGroupOptions;
      this.foodGroup = 'Corporate Party Politics';
      this.onFoodGroupChange('Corporate Party Politics');
    } else if (category === 'Independent') {
      this.filteredFoodGroupOptions = this.independentFoodGroupOptions;
      if (this.foodGroup === 'Corporate Party Politics') {
        this.foodGroup = '';
        this.viewpoint = '';
        this.filteredViewpointOptions = [...this.allViewpointOptions];
      }
    } else {
      this.filteredFoodGroupOptions = [...this.allFoodGroupOptions];
    }
  }

  onFoodGroupChange(foodGroup: string): void {
    const partyGroups = ['Corporate Party Politics', 'Independent Party Politics'];
    if (partyGroups.includes(foodGroup)) {
      this.filteredViewpointOptions = this.partyViewpointOptions;
      if (!['Democrat', 'Republican'].includes(this.viewpoint)) this.viewpoint = '';
    } else if (foodGroup === 'Independent True Politics') {
      this.filteredViewpointOptions = this.trueViewpointOptions;
      if (!['Progressive', 'Conservative'].includes(this.viewpoint)) this.viewpoint = '';
    } else {
      this.filteredViewpointOptions = [...this.allViewpointOptions];
    }
  }

  get hasAtLeastOneLink(): boolean {
    return (
      this.linkToRead.trim().length > 0 ||
      this.linkToWatch.trim().length > 0 ||
      this.linkToListen.trim().length > 0
    );
  }

  get isFormValid(): boolean {
    return (
      this.name.trim().length > 0 &&
      this.description.trim().length > 0 &&
      this.type.length > 0 &&
      this.category.length > 0 &&
      this.foodGroup.length > 0 &&
      this.viewpoint.length > 0 &&
      this.hasAtLeastOneLink
    );
  }

  async save(): Promise<void> {
    if (!this.isFormValid) return;
    this.isSaving = true;
    try {
      const doc: any = {
        name: this.name.trim(),
        description: this.description.trim(),
        type: this.type,
        category: this.category,
        foodGroup: this.foodGroup,
        viewpoint: this.viewpoint,
        hasPaywall: this.hasPaywall,
        imageName: this.imageName.trim(),
      };

      if (this.year !== null) doc.year = this.year;
      if (this.journalistName.trim()) doc.journalistName = this.journalistName.trim();
      if (this.linkToRead.trim()) doc.linkToRead = this.linkToRead.trim();
      if (this.linkToWatch.trim()) doc.linkToWatch = this.linkToWatch.trim();
      if (this.linkToListen.trim()) doc.linkToListen = this.linkToListen.trim();

      await this.firestore.collection('newsSources').add(doc);
      this.message.success('News source saved successfully!');
      this.resetForm();
    } catch (err) {
      console.error('Error saving news source:', err);
      this.message.error('Failed to save news source. Please try again.');
    } finally {
      this.isSaving = false;
    }
  }

  private resetForm(): void {
    this.name = '';
    this.description = '';
    this.type = '';
    this.category = '';
    this.foodGroup = '';
    this.viewpoint = '';
    this.year = null;
    this.journalistName = '';
    this.hasPaywall = false;
    this.linkToRead = '';
    this.linkToWatch = '';
    this.linkToListen = '';
    this.imageName = '';
    this.similarSources = [];
    this.filteredFoodGroupOptions = [...this.allFoodGroupOptions];
    this.filteredViewpointOptions = [...this.allViewpointOptions];
  }
}
