import { UsersService } from 'src/app/services/users.service';
import { Component } from '@angular/core';
import { DietsService } from 'src/app/services/diets.service';
import { User } from '../user.model';
import { Diet } from 'src/app/diet-grid/diet.model';
import { DietGridComponent } from 'src/app/diet-grid/diet-grid.component';

@Component({
  selector: 'custom-diet',
  templateUrl: './custom-diet.component.html',
  styleUrl: './custom-diet.component.scss',
})
export class CustomDietComponent {
  user: User;
  userDiet: Diet;

  constructor(private usersSvc: UsersService, private dietsSvc: DietsService) {}

  ngOnInit(): void {
    this.usersSvc.combinedUser$.subscribe((combinedUser) => {
      if (combinedUser) {
        console.log('[CUSTOM DIET] Combined User!', combinedUser);
        this.user = combinedUser;
      }
    });
  }
}
