import { Component, OnInit, OnDestroy } from '@angular/core';
import { AngularFirestore } from '@angular/fire/compat/firestore';
import { NzMessageService } from 'ng-zorro-antd/message';
import { Subscription } from 'rxjs';

interface NewsSource {
  docId: string;
  name: string;
  foodGroup: string;
  viewpoint: string;
}

interface SourceOption {
  label: string;
  value: string;
}

interface Weekday {
  name: string;
  day: number;
  selectedDocIds: string[];
}

@Component({
  selector: 'app-diet-create',
  templateUrl: './diet-create.component.html',
  styleUrls: ['./diet-create.component.scss'],
})
export class DietCreateComponent implements OnInit, OnDestroy {
  title = '';
  subtitle = '';
  time = '';
  description = '';
  year: number = new Date().getFullYear();
  dietLevel: number = 1;
  custom: boolean = true;

  dietLevelOptions = [
    { label: '1 - Basic', value: 1 },
    { label: '2 - Intermediate', value: 2 },
    { label: '3 - Expert', value: 3 },
  ];

  customOptions = [
    { label: 'Custom (user-created)', value: true },
    { label: 'Standard (site diet)', value: false },
  ];

  newsSources: NewsSource[] = [];
  sourceOptions: SourceOption[] = [];
  isSaving = false;

  weekdays: Weekday[] = [
    { name: 'Sunday', day: 0, selectedDocIds: [] },
    { name: 'Monday', day: 1, selectedDocIds: [] },
    { name: 'Tuesday', day: 2, selectedDocIds: [] },
    { name: 'Wednesday', day: 3, selectedDocIds: [] },
    { name: 'Thursday', day: 4, selectedDocIds: [] },
    { name: 'Friday', day: 5, selectedDocIds: [] },
    { name: 'Saturday', day: 6, selectedDocIds: [] },
  ];

  private sourceSub: Subscription | null = null;

  constructor(private firestore: AngularFirestore, private message: NzMessageService) {}

  ngOnInit(): void {
    this.sourceSub = this.firestore
      .collection('newsSources', (ref) => ref.orderBy('name'))
      .get()
      .subscribe((snapshot) => {
        this.newsSources = snapshot.docs.map((doc) => {
          const data = doc.data() as any;
          return {
            docId: doc.id,
            name: data['name'] ?? '',
            foodGroup: data['foodGroup'] ?? '',
            viewpoint: data['viewpoint'] ?? '',
          };
        });
        this.sourceOptions = this.newsSources.map((s) => ({
          label: `${s.name} — ${s.foodGroup}`,
          value: s.docId,
        }));
      });
  }

  ngOnDestroy(): void {
    this.sourceSub?.unsubscribe();
  }

  trackByDay(_index: number, weekday: Weekday): number {
    return weekday.day;
  }

  onSourcesChange(weekday: Weekday, docIds: string[]): void {
    weekday.selectedDocIds = docIds;
  }

  get isFormValid(): boolean {
    return this.title.trim().length > 0 && this.description.trim().length > 0;
  }

  async saveDiet(): Promise<void> {
    if (!this.isFormValid) return;

    const dietDays = this.weekdays.map((weekday) => ({
      day: weekday.day,
      dayName: weekday.name,
      newsSourceIds: [...weekday.selectedDocIds],
    }));

    this.isSaving = true;
    try {
      await this.firestore.collection('diets').add({
        title: this.title.trim(),
        subtitle: this.subtitle.trim(),
        time: this.time.trim(),
        description: this.description.trim(),
        year: this.year,
        dietLevel: this.dietLevel,
        custom: this.custom,
        dietDays,
      });
      this.message.success('Diet saved successfully!');
      this.resetForm();
    } catch (err) {
      console.error('Error saving diet:', err);
      this.message.error('Failed to save diet. Please try again.');
    } finally {
      this.isSaving = false;
    }
  }

  private resetForm(): void {
    this.title = '';
    this.subtitle = '';
    this.time = '';
    this.description = '';
    this.year = new Date().getFullYear();
    this.dietLevel = 1;
    this.custom = true;
    this.weekdays.forEach((wd) => (wd.selectedDocIds = []));
  }
}
